    this.generation=mk(U);this.free=[];for(let i=C-1;i>=0;i--)this.free.push(i);this.grid=new SpatialGrid(opts.cellSize||12);this.near=[];this.player=-1;this.input={forward:0,right:0,up:0,sprint:false,bite:false,yaw:0,pitch:0};this.camera={x:0,y:0,z:0,tx:0,ty:0,tz:0,distance:8,fov:68};
