  spawnFish(si,x,y,z,isPlayer=false,region=0){const i=this.alloc(KIND.FISH);if(i<0)return-1;const s=SPECIES[si];this.species[i]=si;this.x[i]=x;this.y[i]=y;this.z[i]=z;this.size[i]=s.size;this.level[i]=1;this.xp[i]=0;this.nextXp[i]=this.requiredXP(1);this.maxHp[i]=s.hp;this.hp[i]=s.hp;this.attack[i]=s.attack;this.mass[i]=Math.pow(s.size,3);this.radius[i]=s.size*.72;this.hunger[i]=this.rng.range(.2,.75);this.state[i]=STATE.WANDER;this.aiClock[i]=this.rng.range(0,.2);this.region[i]=region;this.wanderYaw[i]=this.rng.range(-Math.PI,Math.PI);this.wanderPitch[i]=this.rng.range(-.25,.25);this.fx[i]=Math.sin(this.wanderYaw[i]);this.fz[i]=Math.cos(this.wanderYaw[i]);this.isPlayer[i]=isPlayer?1:0;this.temperament[i]=!isPlayer&&si<=3&&this.rng.next()<.09?1:0;this.burstCooldown[i]=this.rng.range(.4,2.5);if(isPlayer)this.player=i;return i}
  spawnFood(kind,x,y,z,nutrition,size=.24,tier=0){const i=this.alloc(kind);if(i<0)return-1;this.x[i]=x;this.y[i]=y;this.z[i]=z;this.size[i]=size;this.radius[i]=size;this.xp[i]=nutrition;this.meatTier[i]=kind===KIND.MEAT?(tier||1):0;this.decay[i]=kind===KIND.MEAT?55:90;return i}
  reset(){for(let i=0;i<this.capacity;i++)this.alive[i]=0;this.free.length=0;for(let i=this.capacity-1;i>=0;i--)this.free.push(i);Object.keys(this.stats).forEach(k=>this.stats[k]=0);this.time=this.tick=this.accumulator=0;this.player=this.spawnFish(PLAYER_SPECIES,-72,-5,25,true,0);for(let r=0;r<REGIONS.length;r++)for(let n=0;n<REGIONS[r].target;n++)this.spawnRegionFish(r);for(let n=0;n<18;n++){const r=this.rng.int(2),q=REGIONS[r];const p=this.randomInRegion(q);this.spawnFood(KIND.PLANT,p[0],p[1],p[2],3,.18)}this.grid.rebuild(this);this.updateCamera(1)}
  randomInRegion(q){if(q.clusters?.length){const c=q.clusters[this.rng.int(q.clusters.length)],a=this.rng.range(0,TAU),d=Math.sqrt(this.rng.next())*this.rng.range(6,15);return[c[0]+Math.cos(a)*d,clamp(c[1]+this.rng.range(-4,4),q.depth[0],q.depth[1]),c[2]+Math.sin(a)*d]}const a=this.rng.range(0,TAU),d=Math.sqrt(this.rng.next())*q.radius;return[q.center[0]+Math.cos(a)*d,this.rng.range(q.depth[0],q.depth[1]),q.center[2]+Math.sin(a)*d]}
