  requiredXP(level){return Math.round(12*Math.pow(level,1.35))}
  advance(realDt){this.accumulator+=Math.min(this.maxFrame,Math.max(0,realDt));let n=0;while(this.accumulator>=this.fixedDt&&n<8){this.step(this.fixedDt);this.accumulator-=this.fixedDt;n++}return n}
