  decide(i){const s=SPECIES[this.species[i]],near=this.grid.query(this,this.x[i],this.y[i],this.z[i],s.vision,this.near);let prey=-1,pred=-1,food=-1,preyScore=-1,predScore=-1,foodScore=-1;for(const j of near){if(j===i||!this.alive[j])continue;const dx=this.x[j]-this.x[i],dy=this.y[j]-this.y[i],dz=this.z[j]-this.z[i],d2=dx*dx+dy*dy+dz*dz;if(this.kind[j]===KIND.FISH){const ratio=this.size[j]/this.size[i],berserkPlayer=this.temperament[i]===1&&this.isPlayer[j]&&ratio>1&&ratio<2.15;if(berserkPlayer){const sc=(2.2-ratio)/(d2+2)*1.8;if(sc>preyScore){prey=j;preyScore=sc}}else if(ratio>1.32/s.fear&&d2>0){const sc=ratio*ratio/(d2+2);if(sc>predScore){pred=j;predScore=sc}}else if(s.diet!==DIET.PLANT&&ratio<.86&&d2>0){const sc=(1-ratio)/(d2+3)*(s.aggression+.2);if(sc>preyScore){prey=j;preyScore=sc}}}else if((this.kind[j]===KIND.MEAT&&s.diet!==DIET.PLANT)||(this.kind[j]===KIND.PLANT&&s.diet!==DIET.MEAT)){const sc=this.xp[j]/(d2+2);if(sc>foodScore){food=j;foodScore=sc}}}
    if(pred>=0){this.target[i]=pred;this.state[i]=STATE.FLEE;this.startBurst(i,true)}else if(prey>=0&&(this.temperament[i]===1||s.aggression*(.55+this.hunger[i])>.36)){this.target[i]=prey;this.state[i]=STATE.CHASE;this.startBurst(i,false)}else if(food>=0){this.target[i]=food;this.state[i]=STATE.EAT}else{this.target[i]=-1;this.state[i]=STATE.WANDER;this.wanderYaw[i]+=(this.rng.next()-.5)*.42;this.wanderPitch[i]=clamp(this.wanderPitch[i]+(this.rng.next()-.5)*.12,-.28,.28);if(this.rng.next()<.035)this.startBurst(i,false)}}
